INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-4', 'original-cet4-2026-1', 3, 'reading', '阅读理解 · The label and the decision', '阅读短文，选择最合适的答案。', '["Nora wanted to buy vegetables for a student cooking class. One shop displayed attractive green labels on every packet. Another provided a plain list showing where each vegetable came from and when it had arrived. The green labels looked impressive, but they did not answer Nora''s questions about freshness or price.","She compared the vegetables themselves, asked about delivery times and chose a mixture from both shops. Later, she showed the class her receipts. Some students were surprised that there was no single label they could follow. Nora explained that useful information had to match the decision being made. A label might tell buyers something important, but it could not replace every other question."]', '["Nora wanted to buy vegetables for a student cooking class. One shop displayed attractive green labels on every packet. Another provided a plain list showing where each vegetable came from and when it had arrived. The green labels looked impressive, but they did not answer Nora''s questions about freshness or price.","She compared the vegetables themselves, asked about delivery times and chose a mixture from both shops. Later, she showed the class her receipts. Some students were surprised that there was no single label they could follow. Nora explained that useful information had to match the decision being made. A label might tell buyers something important, but it could not replace every other question."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-4-q-1', 'original-cet4-2026-1-section-4', 0, 'choice', 'Why was Nora dissatisfied with the green labels?', '[{"key":"A","text":"They were difficult to print."},{"key":"B","text":"They did not provide the information she needed."},{"key":"C","text":"They made every vegetable cheaper."},{"key":"D","text":"They showed that the shop was closed."}]', 'B', 'Nora 需要新鲜度和价格信息，而标签没有回答这些问题。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-4-q-2', 'original-cet4-2026-1-section-4', 1, 'choice', 'What did Nora do before buying?', '[{"key":"A","text":"She chose the largest packets."},{"key":"B","text":"She avoided speaking to sellers."},{"key":"C","text":"She copied another customer''s order."},{"key":"D","text":"She compared products and asked questions."}]', 'D', '第二段写到比较蔬菜并询问送货时间。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-4-q-3', 'original-cet4-2026-1-section-4', 2, 'choice', 'What is the central message?', '[{"key":"A","text":"A useful choice depends on several relevant kinds of information."},{"key":"B","text":"Attractive labels always indicate poor quality."},{"key":"C","text":"Receipts are unnecessary in cooking classes."},{"key":"D","text":"One shop should provide all campus food."}]', 'A', '文章强调信息应服务具体决策，单个标签不能替代全部判断。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet4-2026-1-section-4-sentence-1-1', 'original-cet4-2026-1', 300, 0, 'Nora wanted to buy vegetables for a student cooking class.', 'original-cet4-2026-1-section-4') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
