INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-6', 'original-cet4-2026-1', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["校园里的一间旧教室被改造成了共享修理室。学生可以在志愿者的帮助下修理日常用品，也可以把不再使用的工具捐给其他人。这个小空间不仅减少了浪费，还让不同专业的学生有机会一起解决实际问题。"]', '["An old classroom on campus has been turned into a shared repair room. Students can repair everyday items with help from volunteers, or donate tools they no longer use. This small space reduces waste and gives students from different majors a chance to solve practical problems together."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-6-q-1', 'original-cet4-2026-1-section-6', 0, 'text', '将上文译成英文。', '[]', 'An old classroom on campus has been turned into a shared repair room. Students can repair everyday items with help from volunteers, or donate tools they no longer use. This small space reduces waste and gives students from different majors a chance to solve practical problems together.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet4-2026-2', 'CET4', 2026, 10, 2, '主题练习', '四级主题练习 02 · 习惯与自信', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet4-2', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。主题参考：运动习惯、自我评价与文化交流。', 'cet4-2026-06-2') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-1', 'original-cet4-2026-2', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Joining a new club can be difficult when everyone else seems experienced. A student club can make the first step easier by offering a beginner session each month. During this session, members should explain basic activities and let newcomers try a small task without being judged. Pairing a new student with a friendly member would also help. The partner could answer questions and explain what happens at regular meetings. It is equally useful to celebrate progress rather than compare people. A beginner who learns one skill deserves encouragement even if others can do much more. Finally, clubs should ask new members what made them comfortable or confused. These comments can improve the next welcome session. Confidence develops through manageable experiences, so a good club should give beginners reasons to return."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-1-q-1', 'original-cet4-2026-2-section-1', 0, 'text', 'Write 120–180 words suggesting how a student club can help beginners take part with confidence.', '[]', 'Joining a new club can be difficult when everyone else seems experienced. A student club can make the first step easier by offering a beginner session each month. During this session, members should explain basic activities and let newcomers try a small task without being judged. Pairing a new student with a friendly member would also help. The partner could answer questions and explain what happens at regular meetings. It is equally useful to celebrate progress rather than compare people. A beginner who learns one skill deserves encouragement even if others can do much more. Finally, clubs should ask new members what made them comfortable or confused. These comments can improve the next welcome session. Confidence develops through manageable experiences, so a good club should give beginners reasons to return.', '核对措施是否具体、是否围绕初学者，并用例子说明如何降低参与门槛。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-2', 'original-cet4-2026-2', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["Mina joined a running club but struggled to [1] ______ a daily routine. The coach suggested a shorter route that was [2] ______ for beginners. Rather than comparing her speed with others, she kept a record of small [3] ______. A friend agreed to [4] ______ her about the weekly meeting. Mina eventually found that a [5] ______ habit was easier to build when the activity fitted her life."]', '["Mina joined a running club but struggled to maintain a daily routine. The coach suggested a shorter route that was suitable for beginners. Rather than comparing her speed with others, she kept a record of small improvements. A friend agreed to remind her about the weekly meeting. Mina eventually found that a regular habit was easier to build when the activity fitted her life."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-2-q-1', 'original-cet4-2026-2-section-2', 0, 'choice', '第 1 空', '[{"key":"A","text":"regular"},{"key":"B","text":"remind"},{"key":"C","text":"improvements"},{"key":"D","text":"maintain"},{"key":"E","text":"suitable"},{"key":"F","text":"forget"},{"key":"G","text":"rapidly"},{"key":"H","text":"distance"}]', 'D', '第 1 空填入 maintain，结合上下文和句法关系判断。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
