INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-3', 'original-cet4-2026-2', 2, 'matching', '信息匹配 · 初学者的空间', '根据段落内容完成匹配。', '["[A] At the language café, nobody corrects every mistake during a conversation. The host writes down a few useful expressions and discusses them afterwards. Participants can finish their stories without constant interruption. The aim is to practise communication before worrying about perfect performance.","[B] The beginner music group lends instruments for the first month. Students can explore whether they enjoy playing before spending money. A short meeting explains how to look after each instrument, and there is a simple form for reporting damage.","[C] The swimming club reserves a quiet lane for nervous learners. The coach first teaches them to stand safely in shallow water. Only when they feel ready do they move to a harder exercise. Completing the same lesson quickly is not expected of everyone.","[D] The drawing circle displays early sketches beside later work. Visitors can see crossed-out lines and unfinished ideas as well as polished pictures. Members say that this display reminds them that skill grows through attempts that may look disappointing at first."]', '["At the language café, nobody corrects every mistake during a conversation. The host writes down a few useful expressions and discusses them afterwards. Participants can finish their stories without constant interruption. The aim is to practise communication before worrying about perfect performance.","The beginner music group lends instruments for the first month. Students can explore whether they enjoy playing before spending money. A short meeting explains how to look after each instrument, and there is a simple form for reporting damage.","The swimming club reserves a quiet lane for nervous learners. The coach first teaches them to stand safely in shallow water. Only when they feel ready do they move to a harder exercise. Completing the same lesson quickly is not expected of everyone.","The drawing circle displays early sketches beside later work. Visitors can see crossed-out lines and unfinished ideas as well as polished pictures. Members say that this display reminds them that skill grows through attempts that may look disappointing at first."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
