INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-4', 'original-cet4-2026-2', 3, 'reading', '阅读理解 · Who wrote the notes?', '阅读短文，选择最合适的答案。', '["When Leo received praise for a clear group presentation, he felt uncomfortable. He believed that another student had done all the important work. His tutor asked him to bring the group''s planning notes to their next meeting rather than simply argue about whether he deserved the praise.","The notes showed that Leo had found the examples, removed repeated slides and practised the conclusion with the team. Seeing these actions did not make him believe that he was perfect. It gave him a more accurate account of his contribution. His tutor suggested recording specific actions after future projects. Evidence of work was more useful than telling himself either that he was brilliant or that he had contributed nothing."]', '["When Leo received praise for a clear group presentation, he felt uncomfortable. He believed that another student had done all the important work. His tutor asked him to bring the group''s planning notes to their next meeting rather than simply argue about whether he deserved the praise.","The notes showed that Leo had found the examples, removed repeated slides and practised the conclusion with the team. Seeing these actions did not make him believe that he was perfect. It gave him a more accurate account of his contribution. His tutor suggested recording specific actions after future projects. Evidence of work was more useful than telling himself either that he was brilliant or that he had contributed nothing."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-4-q-1', 'original-cet4-2026-2-section-4', 0, 'choice', 'What did the tutor ask Leo to examine?', '[{"key":"A","text":"His marks from earlier years."},{"key":"B","text":"The group''s planning notes."},{"key":"C","text":"Other students'' personal diaries."},{"key":"D","text":"The size of the audience."}]', 'B', '导师要求带来小组计划笔记，用记录核对贡献。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-4-q-2', 'original-cet4-2026-2-section-4', 1, 'choice', 'The notes helped Leo _____.', '[{"key":"A","text":"claim that nobody else worked"},{"key":"B","text":"avoid every future presentation"},{"key":"C","text":"identify his actual contribution"},{"key":"D","text":"prove that his slides were perfect"}]', 'C', '笔记列出了他实际完成的任务。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-4-q-3', 'original-cet4-2026-2-section-4', 2, 'choice', 'Which title best fits the passage?', '[{"key":"A","text":"Replacing Self-Judgment with Evidence"},{"key":"B","text":"Why Group Work Should End"},{"key":"C","text":"The Value of a Larger Audience"},{"key":"D","text":"A Perfect Student Never Doubts"}]', 'A', '文章主张用具体证据获得更准确的自我评价。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
