INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet4-2026-2-section-4-sentence-2-5', 'original-cet4-2026-2', 301, 4, 'Evidence of work was more useful than telling himself either that he was brilliant or that he had contributed nothing.', 'original-cet4-2026-2-section-4') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-5', 'original-cet4-2026-2', 4, 'reading', '阅读理解 · A rhythm everyone could enter', '阅读短文，选择最合适的答案。', '["At an international student evening, the organisers first planned a competition between national music groups. A volunteer proposed a different format: everyone would learn a simple rhythm and then add something from their own experience. No performance would be ranked.","The first attempt was uneven. Some students started early, and others were afraid of making mistakes. The leader slowed the rhythm and invited people to listen before joining. Gradually, the sound became more varied and more coordinated. The evening did not remove cultural differences. It created a shared activity in which those differences had a place, while giving people enough structure to work together."]', '["At an international student evening, the organisers first planned a competition between national music groups. A volunteer proposed a different format: everyone would learn a simple rhythm and then add something from their own experience. No performance would be ranked.","The first attempt was uneven. Some students started early, and others were afraid of making mistakes. The leader slowed the rhythm and invited people to listen before joining. Gradually, the sound became more varied and more coordinated. The evening did not remove cultural differences. It created a shared activity in which those differences had a place, while giving people enough structure to work together."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-5-q-1', 'original-cet4-2026-2-section-5', 0, 'choice', 'How did the volunteer''s proposal differ from the original plan?', '[{"key":"A","text":"It required expensive tickets."},{"key":"B","text":"It replaced shared rhythm with silence."},{"key":"C","text":"It excluded new performers."},{"key":"D","text":"It replaced competition with participation."}]', 'D', '新方案共同学节奏并加入个人经验，不再排名。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-5-q-2', 'original-cet4-2026-2-section-5', 1, 'choice', 'Why did the leader slow the rhythm?', '[{"key":"A","text":"To announce the winners."},{"key":"B","text":"To help hesitant participants join."},{"key":"C","text":"To shorten the entire event."},{"key":"D","text":"To remove cultural variation."}]', 'B', '起步不齐、有人害怕犯错，因此放慢节奏帮助参与。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-5-q-3', 'original-cet4-2026-2-section-5', 2, 'choice', 'What does the passage suggest about shared activities?', '[{"key":"A","text":"They require people to abandon their backgrounds."},{"key":"B","text":"They must always produce the same sound."},{"key":"C","text":"They can combine common structure with differences."},{"key":"D","text":"They are useful only when perfectly performed."}]', 'C', '共同节奏提供结构，各自经验保留差异。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
