INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-2-section-6', 'original-cet4-2026-2', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["社区图书馆每周举办一次语言交流活动。参加者可以分享家乡的故事，也可以介绍自己喜欢的书。工作人员准备了简单的话题卡片，让第一次参加的人更容易开口。活动不追求毫无错误的表达，而是鼓励大家耐心倾听、相互理解。"]', '["The community library holds a language exchange once a week. Participants can share stories about their hometowns or introduce books they enjoy. Staff prepare simple topic cards to make it easier for first-time visitors to speak. The activity encourages patient listening and mutual understanding rather than error-free expression."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-2-section-6-q-1', 'original-cet4-2026-2-section-6', 0, 'text', '将上文译成英文。', '[]', 'The community library holds a language exchange once a week. Participants can share stories about their hometowns or introduce books they enjoy. Staff prepare simple topic cards to make it easier for first-time visitors to speak. The activity encourages patient listening and mutual understanding rather than error-free expression.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet4-2026-3', 'CET4', 2026, 10, 3, '主题练习', '四级主题练习 03 · 研究与沟通', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet4-3', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。主题参考：学生研究、求职沟通与日常习惯。', 'cet4-2026-06-3') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-1', 'original-cet4-2026-3', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["A small research project can help students improve campus services by replacing guesses with evidence. For example, a team could study why the bicycle parking area near the library is often crowded. They could count bicycles at different times, interview users and draw a map of the available spaces. These methods would reveal whether the problem came from too few spaces, unclear signs or abandoned bicycles. The students should protect people''s privacy and avoid collecting information they do not need. After examining the results, they could recommend one affordable change and test it for a week. The project would teach them to ask clear questions, cooperate and evaluate an idea. It would also show that useful research does not always require expensive equipment. Careful observation can be a good starting point."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-1-q-1', 'original-cet4-2026-3-section-1', 0, 'text', 'Write 120–180 words explaining how a small research project could improve one campus service. Use an example of your own.', '[]', 'A small research project can help students improve campus services by replacing guesses with evidence. For example, a team could study why the bicycle parking area near the library is often crowded. They could count bicycles at different times, interview users and draw a map of the available spaces. These methods would reveal whether the problem came from too few spaces, unclear signs or abandoned bicycles. The students should protect people''s privacy and avoid collecting information they do not need. After examining the results, they could recommend one affordable change and test it for a week. The project would teach them to ask clear questions, cooperate and evaluate an idea. It would also show that useful research does not always require expensive equipment. Careful observation can be a good starting point.', '核对研究问题、方法、改进建议是否一致，是否提到可行性与隐私边界。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-2', 'original-cet4-2026-3', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A student team wanted to improve an online appointment service. They began by [1] ______ how visitors used it. Their first [2] ______ was that the buttons were too small, but interviews suggested a different problem. The available times were not [3] ______ explained. The team tested a new page and asked users for [4] ______. They decided to keep collecting evidence before reaching a final [5] ______."]', '["A student team wanted to improve an online appointment service. They began by observing how visitors used it. Their first assumption was that the buttons were too small, but interviews suggested a different problem. The available times were not clearly explained. The team tested a new page and asked users for feedback. They decided to keep collecting evidence before reaching a final conclusion."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
