INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-3', 'original-cet4-2026-3', 2, 'matching', '信息匹配 · 面试准备', '根据段落内容完成匹配。', '["[A] Before a video interview, Jo practised explaining one project to a friend. The friend interrupted whenever a term was unclear. Jo then replaced unnecessary technical words with concrete examples. This helped her describe her work to someone outside her course.","[B] Sam placed a short list of questions beside his screen. He wanted to understand how interns would receive training and feedback. The list prevented him from forgetting what mattered when the conversation became busy. He still listened rather than reading the questions mechanically.","[C] The interviewer offered Anika a chance to begin again after the connection failed. Anika briefly explained what had happened and repeated only the part that had been lost. A calm explanation was more useful than apologising throughout the rest of the meeting.","[D] After the interview, Ben wrote down a question that had been difficult to answer. He checked his project records and prepared a clearer example for next time. He did not assume that one uncomfortable answer proved he was unsuited to the whole field."]', '["Before a video interview, Jo practised explaining one project to a friend. The friend interrupted whenever a term was unclear. Jo then replaced unnecessary technical words with concrete examples. This helped her describe her work to someone outside her course.","Sam placed a short list of questions beside his screen. He wanted to understand how interns would receive training and feedback. The list prevented him from forgetting what mattered when the conversation became busy. He still listened rather than reading the questions mechanically.","The interviewer offered Anika a chance to begin again after the connection failed. Anika briefly explained what had happened and repeated only the part that had been lost. A calm explanation was more useful than apologising throughout the rest of the meeting.","After the interview, Ben wrote down a question that had been difficult to answer. He checked his project records and prepared a clearer example for next time. He did not assume that one uncomfortable answer proved he was unsuited to the whole field."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-3-q-1', 'original-cet4-2026-3-section-3', 0, 'choice', 'A technical interruption is handled with a brief explanation.', '[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"}]', 'C', 'C 段连接中断后简要说明并重述缺失部分。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
