INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-3-q-3', 'original-cet4-2026-3-section-3', 2, 'choice', 'Reflection turns a difficult answer into later preparation.', '[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"}]', 'D', 'D 段把难答的问题用于下一次准备。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
