INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet4-2026-3-section-3-sentence-4-3', 'original-cet4-2026-3', 203, 2, 'He did not assume that one uncomfortable answer proved he was unsuited to the whole field.', 'original-cet4-2026-3-section-3') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-4', 'original-cet4-2026-3', 3, 'reading', '阅读理解 · The study behind the survey', '阅读短文，选择最合适的答案。', '["A campus café wanted to know whether students preferred a longer menu. The manager placed a survey beside the counter at noon. Most respondents asked for more hot meals. The manager almost ordered a new cooking unit, but a student researcher noticed that the survey had reached mainly lunch customers.","The researcher returned in the morning and evening. Early visitors cared about quick service, while later visitors wanted a quiet place to study. The café tested different arrangements at different times instead of extending the menu all day. The first survey had not been useless; it had answered a narrower question than the manager originally thought. Knowing who supplied the evidence changed how that evidence could be used."]', '["A campus café wanted to know whether students preferred a longer menu. The manager placed a survey beside the counter at noon. Most respondents asked for more hot meals. The manager almost ordered a new cooking unit, but a student researcher noticed that the survey had reached mainly lunch customers.","The researcher returned in the morning and evening. Early visitors cared about quick service, while later visitors wanted a quiet place to study. The café tested different arrangements at different times instead of extending the menu all day. The first survey had not been useless; it had answered a narrower question than the manager originally thought. Knowing who supplied the evidence changed how that evidence could be used."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-4-q-1', 'original-cet4-2026-3-section-4', 0, 'choice', 'What was the limitation of the first survey?', '[{"key":"A","text":"It mainly represented lunch customers."},{"key":"B","text":"It asked about an unrelated building."},{"key":"C","text":"It was completed only by staff."},{"key":"D","text":"It included no questions about food."}]', 'A', '调查只在中午开展，样本偏向午餐顾客。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-4-q-2', 'original-cet4-2026-3-section-4', 1, 'choice', 'What did the café eventually try?', '[{"key":"A","text":"A cooking unit for every table."},{"key":"B","text":"The same arrangement all day."},{"key":"C","text":"Different arrangements for different times."},{"key":"D","text":"Closing during the evening."}]', 'C', '后续结果显示不同时段需求不同，因此分时测试。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-4-q-3', 'original-cet4-2026-3-section-4', 2, 'choice', 'What lesson does the passage offer?', '[{"key":"A","text":"Long menus always cause waste."},{"key":"B","text":"The source of evidence affects its interpretation."},{"key":"C","text":"Customers never understand surveys."},{"key":"D","text":"Small studies cannot improve services."}]', 'B', '调查对象决定了证据可以支持什么结论。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
