INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-5', 'original-cet4-2026-3', 4, 'reading', '阅读理解 · A pause before the reply', '阅读短文，选择最合适的答案。', '["During a group meeting, a message from an absent member appeared on the screen: the latest plan was \"not ready\". Rui felt that his work had been dismissed and immediately began writing an angry reply. Before sending it, he asked another member to read the message with him.","They noticed that the message also requested missing cost figures. Rui asked which figures were needed and learned that the absent member was preparing a funding application. The plan had not been rejected; it needed information for a different purpose. Rui kept a simple rule after that meeting: when a short message seems hostile, clarify its meaning before deciding how to respond. The rule did not guarantee agreement, but it prevented some avoidable arguments."]', '["During a group meeting, a message from an absent member appeared on the screen: the latest plan was \"not ready\". Rui felt that his work had been dismissed and immediately began writing an angry reply. Before sending it, he asked another member to read the message with him.","They noticed that the message also requested missing cost figures. Rui asked which figures were needed and learned that the absent member was preparing a funding application. The plan had not been rejected; it needed information for a different purpose. Rui kept a simple rule after that meeting: when a short message seems hostile, clarify its meaning before deciding how to respond. The rule did not guarantee agreement, but it prevented some avoidable arguments."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-5-q-1', 'original-cet4-2026-3-section-5', 0, 'choice', 'What did Rui initially believe?', '[{"key":"A","text":"The application had already succeeded."},{"key":"B","text":"The meeting had been cancelled."},{"key":"C","text":"The message praised the plan."},{"key":"D","text":"The message dismissed his work."}]', 'D', 'Rui 一开始认为自己的工作被否定。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-5-q-2', 'original-cet4-2026-3-section-5', 1, 'choice', 'Why were the cost figures requested?', '[{"key":"A","text":"To arrange a sports competition."},{"key":"B","text":"To prepare a funding application."},{"key":"C","text":"To replace every team member."},{"key":"D","text":"To publish an angry reply."}]', 'B', '对方正在准备资金申请，需要费用信息。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-5-q-3', 'original-cet4-2026-3-section-5', 2, 'choice', 'What does Rui''s later rule recommend?', '[{"key":"A","text":"Clarifying meaning before responding."},{"key":"B","text":"Never disagreeing with others."},{"key":"C","text":"Answering every message immediately."},{"key":"D","text":"Ignoring all requests for information."}]', 'A', '短消息看似不友好时，先核对其含义。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
