INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-3-section-6', 'original-cet4-2026-3', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["一些大学正在鼓励学生参加社区调查。学生先与居民交谈，了解他们在生活中遇到的困难，再把观察结果整理成报告。通过这样的实践，学生能够学习如何提出问题、收集证据并尊重不同意见。他们的建议也可能为社区服务的改进提供帮助。"]', '["Some universities are encouraging students to conduct community surveys. Students first talk with residents about difficulties in their daily lives and then organise their observations into reports. Through this practice, students can learn to ask questions, gather evidence and respect different opinions. Their suggestions may also help improve community services."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-3-section-6-q-1', 'original-cet4-2026-3-section-6', 0, 'text', '将上文译成英文。', '[]', 'Some universities are encouraging students to conduct community surveys. Students first talk with residents about difficulties in their daily lives and then organise their observations into reports. Through this practice, students can learn to ask questions, gather evidence and respect different opinions. Their suggestions may also help improve community services.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet6-2026-1', 'CET6', 2026, 10, 1, '主题练习', '六级主题练习 01 · 公共选择与长期视角', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet6-1', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考六级试卷中的公共议题、数字生活和政策阅读结构，全文为原创缩编内容。', 'cet6-2026-06-1') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-1', 'original-cet6-2026-1', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["A convenient service is valuable only when people can understand its limits. A map application can find a quick route, but it may not know that a path is closed or unsafe at night. Users should treat digital suggestions as useful information rather than final decisions. Service providers should explain what their systems can and cannot do. Clear notices, updated data and an easy way to report errors can prevent small mistakes from becoming serious problems. Schools can ask students to compare an online recommendation with evidence from the real world. Convenience should save time, not remove judgment. When people understand a tool’s limits, they can use its strengths with greater confidence and remain responsible for their choices."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-1-q-1', 'original-cet6-2026-1-section-1', 0, 'text', 'Write 150–200 words beginning with: “A convenient service is valuable only when people can understand its limits.” Develop your view with reasons or examples.', '[]', 'A convenient service is valuable only when people can understand its limits. A map application can find a quick route, but it may not know that a path is closed or unsafe at night. Users should treat digital suggestions as useful information rather than final decisions. Service providers should explain what their systems can and cannot do. Clear notices, updated data and an easy way to report errors can prevent small mistakes from becoming serious problems. Schools can ask students to compare an online recommendation with evidence from the real world. Convenience should save time, not remove judgment. When people understand a tool’s limits, they can use its strengths with greater confidence and remain responsible for their choices.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-2', 'original-cet6-2026-1', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A city introduced a rent-support programme after a careful [1] ______ of housing costs. Officials did not simply announce a single [2] ______. They compared different neighbourhoods and [3] ______ tenants, landlords and local groups. The first report showed that a short-term payment could help some families but would not [4] ______ the wider shortage. The city therefore combined emergency support with a longer plan to [5] ______ affordable homes."]', '["A city introduced a rent-support programme after a careful assessment of housing costs. Officials did not simply announce a single measure. They compared different neighbourhoods and consulted tenants, landlords and local groups. The first report showed that a short-term payment could help some families but would not resolve the wider shortage. The city therefore combined emergency support with a longer plan to increase affordable homes."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-2-q-1', 'original-cet6-2026-1-section-2', 0, 'choice', '第 1 空', '[{"key":"A","text":"increase"},{"key":"B","text":"resolve"},{"key":"C","text":"consulted"},{"key":"D","text":"assessment"},{"key":"E","text":"measure"},{"key":"F","text":"ignore"},{"key":"G","text":"temporary"},{"key":"H","text":"narrow"}]', 'D', '第 1 空填入 assessment，结合上下文和句法关系判断。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
