INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet6-2026-1-section-2-sentence-1-3', 'original-cet6-2026-1', 100, 2, 'They compared different neighbourhoods and consulted tenants, landlords and local groups.', 'original-cet6-2026-1-section-2') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet6-2026-1-section-2-sentence-1-4', 'original-cet6-2026-1', 100, 3, 'The first report showed that a short-term payment could help some families but would not resolve the wider shortage.', 'original-cet6-2026-1-section-2') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet6-2026-1-section-2-sentence-1-5', 'original-cet6-2026-1', 100, 4, 'The city therefore combined emergency support with a longer plan to increase affordable homes.', 'original-cet6-2026-1-section-2') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-3', 'original-cet6-2026-1', 2, 'matching', '信息匹配 · 公共选择与长期视角', '根据段落内容完成匹配。', '["[A] Remote workers move between cities in search of reliable internet. A small town attracted them by improving its public network and opening quiet work rooms. The project also asked visitors to respect local housing.","[B] A housing survey compared advertised rents with the total cost of living. Transport, heating and travel time changed the apparent advantage of a cheap flat.","[C] A public office replaced a complicated form with a short online version. It kept a paper form and a staffed phone line for people without reliable internet.","[D] A council published its budget in plain language. Residents could see what had been spent and why projects had changed. Attendance at meetings increased."]', '["Remote workers move between cities in search of reliable internet. A small town attracted them by improving its public network and opening quiet work rooms. The project also asked visitors to respect local housing.","A housing survey compared advertised rents with the total cost of living. Transport, heating and travel time changed the apparent advantage of a cheap flat.","A public office replaced a complicated form with a short online version. It kept a paper form and a staffed phone line for people without reliable internet.","A council published its budget in plain language. Residents could see what had been spent and why projects had changed. Attendance at meetings increased."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
