INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-4', 'original-cet6-2026-1', 3, 'reading', '阅读理解 · The cost of a short route', '阅读短文，选择最合适的答案。', '["A delivery company celebrated software that reduced drivers’ average distance. It sent vehicles through a narrow street beside a school, and parents complained about noise. The company measured travel time, fuel use and local disruption together. A slightly longer route avoided the busiest period and produced a more stable arrangement."]', '["A delivery company celebrated software that reduced drivers’ average distance. It sent vehicles through a narrow street beside a school, and parents complained about noise. The company measured travel time, fuel use and local disruption together. A slightly longer route avoided the busiest period and produced a more stable arrangement."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-4-q-1', 'original-cet6-2026-1-section-4', 0, 'choice', 'Why did parents complain?', '[{"key":"A","text":"Vehicles used a school-side street at busy times."},{"key":"B","text":"The software deleted addresses."},{"key":"C","text":"The company stopped deliveries."},{"key":"D","text":"Drivers refused all routes."}]', 'A', '新路线在学校附近繁忙时段通行。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-4-q-2', 'original-cet6-2026-1-section-4', 1, 'choice', 'What did the company measure later?', '[{"key":"A","text":"Only fuel use."},{"key":"B","text":"Travel, fuel and local disruption."},{"key":"C","text":"Only driver numbers."},{"key":"D","text":"The age of vehicles."}]', 'B', '第二句列出三类指标。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-4-q-3', 'original-cet6-2026-1-section-4', 2, 'choice', 'What is the main point?', '[{"key":"A","text":"A short route is always best."},{"key":"B","text":"Efficiency should include hidden costs."},{"key":"C","text":"Complaints are unrelated to planning."},{"key":"D","text":"Software cannot change transport."}]', 'B', '只计算距离会忽略由他人承担的成本。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
