INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-5', 'original-cet6-2026-1', 4, 'reading', '阅读理解 · A policy that learned', '阅读短文，选择最合适的答案。', '["A university required every department to reduce printing. One department removed several printers, then discovered that students with visual difficulties depended on a nearby machine. It tested a shared printer with accessible settings and kept most routine work online. The final policy used less paper without assuming the same solution suited every user."]', '["A university required every department to reduce printing. One department removed several printers, then discovered that students with visual difficulties depended on a nearby machine. It tested a shared printer with accessible settings and kept most routine work online. The final policy used less paper without assuming the same solution suited every user."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-5-q-1', 'original-cet6-2026-1-section-5', 0, 'choice', 'Why was the first change paused?', '[{"key":"A","text":"Some students needed accessible printing."},{"key":"B","text":"Staff wanted more paper."},{"key":"C","text":"The department had no online system."},{"key":"D","text":"A printer was too expensive."}]', 'A', '视力有困难的学生依赖可放大打印。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-5-q-2', 'original-cet6-2026-1-section-5', 1, 'choice', 'What solution was tested?', '[{"key":"A","text":"A shared printer with accessible settings."},{"key":"B","text":"A larger office."},{"key":"C","text":"Printing documents twice."},{"key":"D","text":"Removing online material."}]', 'A', '保留共享打印机并加入无障碍设置。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-5-q-3', 'original-cet6-2026-1-section-5', 2, 'choice', 'A strong policy should _____.', '[{"key":"A","text":"ignore unusual cases"},{"key":"B","text":"learn from affected users"},{"key":"C","text":"avoid measuring results"},{"key":"D","text":"apply one solution everywhere"}]', 'B', '政策应吸收受影响者的反馈。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
