INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-1-section-6', 'original-cet6-2026-1', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["中国许多城市正在改善公共交通，以便让居民更方便地往返工作和生活。除了建设地铁和公交线路，一些城市还增加了自行车道，并通过手机应用提供实时信息。良好的交通系统不仅可以缩短出行时间，还能减少道路拥堵和空气污染。"]', '["Many Chinese cities are improving public transport to make it easier for residents to travel between work and home. In addition to building subway and bus routes, some cities are adding bicycle lanes and providing real-time information through mobile applications. A good transport system can shorten travel time and reduce traffic congestion and air pollution."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-1-section-6-q-1', 'original-cet6-2026-1-section-6', 0, 'text', '将上文译成英文。', '[]', 'Many Chinese cities are improving public transport to make it easier for residents to travel between work and home. In addition to building subway and bus routes, some cities are adding bicycle lanes and providing real-time information through mobile applications. A good transport system can shorten travel time and reduce traffic congestion and air pollution.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet6-2026-2', 'CET6', 2026, 10, 2, '主题练习', '六级主题练习 02 · 科技、风险与判断', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet6-2', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考六级试卷中的金融、生态和数字生活章节，全文为原创缩编内容。', 'cet6-2026-06-2') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-1', 'original-cet6-2026-2', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Universities should teach students how to evaluate information produced by artificial intelligence. AI tools can summarise a large amount of material, but a fluent answer is not necessarily an accurate one. Students need to check sources, compare explanations and recognise when a question requires expert judgment. This training would not mean rejecting AI. A class could ask students to test an AI answer against an academic article and explain every correction. Such work develops digital skills and intellectual honesty. As AI becomes common in study and employment, the ability to question a convenient answer will be as important as the ability to produce one quickly."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-1-q-1', 'original-cet6-2026-2-section-1', 0, 'text', 'Write 150–200 words on whether universities should teach students how to evaluate information produced by artificial intelligence.', '[]', 'Universities should teach students how to evaluate information produced by artificial intelligence. AI tools can summarise a large amount of material, but a fluent answer is not necessarily an accurate one. Students need to check sources, compare explanations and recognise when a question requires expert judgment. This training would not mean rejecting AI. A class could ask students to test an AI answer against an academic article and explain every correction. Such work develops digital skills and intellectual honesty. As AI becomes common in study and employment, the ability to question a convenient answer will be as important as the ability to produce one quickly.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-2', 'original-cet6-2026-2', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A financial crisis can begin with a small [1] ______ that institutions choose to ignore. When borrowers take on [2] ______ debt, a change in interest rates may make repayments difficult. Banks need to [3] ______ whether customers can continue paying. If information is hidden, confidence may [4] ______ quickly. Good regulation cannot remove every risk, but it can make problems more [5] ______ before they spread."]', '["A financial crisis can begin with a small warning that institutions choose to ignore. When borrowers take on excessive debt, a change in interest rates may make repayments difficult. Banks need to assess whether customers can continue paying. If information is hidden, confidence may collapse quickly. Good regulation cannot remove every risk, but it can make problems more visible before they spread."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
