INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-3', 'original-cet6-2026-2', 2, 'matching', '信息匹配 · 科技、风险与判断', '根据段落内容完成匹配。', '["[A] A forest team studied native trees before planting. It copied the mixed structure of remaining woodland instead of planting one fast-growing species.","[B] The team set targets for soil, insects and water as well as tree numbers. Some plots were left alone for comparison.","[C] Farmers feared that a new forest would take land. The organisers changed the boundary and paid local workers to maintain a firebreak.","[D] After rain removed seedlings, the team recorded the failure and changed the planting season."]', '["A forest team studied native trees before planting. It copied the mixed structure of remaining woodland instead of planting one fast-growing species.","The team set targets for soil, insects and water as well as tree numbers. Some plots were left alone for comparison.","Farmers feared that a new forest would take land. The organisers changed the boundary and paid local workers to maintain a firebreak.","After rain removed seedlings, the team recorded the failure and changed the planting season."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
