INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-4', 'original-cet6-2026-2', 3, 'reading', '阅读理解 · The quiet signal', '阅读短文，选择最合适的答案。', '["A wearable device warned cyclists of vehicles behind them. At first it sounded for every nearby object, so users ignored it. Engineers added speed, distance and direction. The device gave a stronger warning only when several signals suggested real risk. A warning must compete for attention carefully: if every event appears urgent, people hear nothing."]', '["A wearable device warned cyclists of vehicles behind them. At first it sounded for every nearby object, so users ignored it. Engineers added speed, distance and direction. The device gave a stronger warning only when several signals suggested real risk. A warning must compete for attention carefully: if every event appears urgent, people hear nothing."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-4-q-1', 'original-cet6-2026-2-section-4', 0, 'choice', 'Why did cyclists ignore the first device?', '[{"key":"A","text":"It warned too often."},{"key":"B","text":"It never sounded."},{"key":"C","text":"It was hard to wear."},{"key":"D","text":"It worked only in rain."}]', 'A', '第一版干扰过多。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-4-q-2', 'original-cet6-2026-2-section-4', 1, 'choice', 'What did engineers add?', '[{"key":"A","text":"A map of every city."},{"key":"B","text":"Several factors for judging risk."},{"key":"C","text":"A rule banning bicycles."},{"key":"D","text":"A larger screen."}]', 'B', '系统结合速度、距离和方向。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-4-q-3', 'original-cet6-2026-2-section-4', 2, 'choice', 'What lesson follows?', '[{"key":"A","text":"Every event should appear urgent."},{"key":"B","text":"Warnings work better when selective."},{"key":"C","text":"People never change habits."},{"key":"D","text":"Silent roads are always dangerous."}]', 'B', '过多警报会使人不再注意。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
