INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-5', 'original-cet6-2026-2', 4, 'reading', '阅读理解 · When a number is not enough', '阅读短文，选择最合适的答案。', '["A museum announced that an online exhibition had received one million visits. The education team examined how long people stayed and which objects they opened. Many visitors looked briefly at a popular image, while a smaller group read background material for much longer. The museum reported both reach and engagement because a large audience alone could not explain the exhibition’s value."]', '["A museum announced that an online exhibition had received one million visits. The education team examined how long people stayed and which objects they opened. Many visitors looked briefly at a popular image, while a smaller group read background material for much longer. The museum reported both reach and engagement because a large audience alone could not explain the exhibition’s value."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-5-q-1', 'original-cet6-2026-2-section-5', 0, 'choice', 'What did the team examine?', '[{"key":"A","text":"How visitors used the exhibition."},{"key":"B","text":"The cost of the website."},{"key":"C","text":"Why the museum closed."},{"key":"D","text":"Which newspaper wrote the headline."}]', 'A', '团队分析停留时间和打开对象。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-5-q-2', 'original-cet6-2026-2-section-5', 1, 'choice', 'What did the results show?', '[{"key":"A","text":"Different kinds of visitors."},{"key":"B","text":"All visitors studied equally."},{"key":"C","text":"Nobody returned."},{"key":"D","text":"The image was unavailable."}]', 'A', '访客存在快速浏览和深入阅读的差异。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-5-q-3', 'original-cet6-2026-2-section-5', 2, 'choice', 'How did the report improve?', '[{"key":"A","text":"It removed the visit number."},{"key":"B","text":"It included reach and engagement."},{"key":"C","text":"It counted teachers only."},{"key":"D","text":"It hid background material."}]', 'B', '同时报告访问量和参与度。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
