INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet6-2026-2-section-5-sentence-1-3', 'original-cet6-2026-2', 400, 2, 'Many visitors looked briefly at a popular image, while a smaller group read background material for much longer.', 'original-cet6-2026-2-section-5') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
