INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-2-section-6', 'original-cet6-2026-2', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["数字技术正在改变人们获取公共服务的方式。在线平台可以帮助居民提交申请、查询进度和获得提醒，但并不是所有人都能熟练使用数字设备。因此，公共机构还应保留电话和面对面的服务渠道，确保技术进步不会制造新的障碍。"]', '["Digital technology is changing the way people access public services. Online platforms can help residents submit applications, check progress and receive reminders, but not everyone can use digital devices with confidence. Public institutions should keep telephone and face-to-face channels so that technological progress does not create new barriers."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-2-section-6-q-1', 'original-cet6-2026-2-section-6', 0, 'text', '将上文译成英文。', '[]', 'Digital technology is changing the way people access public services. Online platforms can help residents submit applications, check progress and receive reminders, but not everyone can use digital devices with confidence. Public institutions should keep telephone and face-to-face channels so that technological progress does not create new barriers.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet6-2026-3', 'CET6', 2026, 10, 3, '主题练习', '六级主题练习 03 · 文化与全球协作', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet6-3', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考六级试卷中的传统文化、艺术技术和全球议题章节，全文为原创缩编内容。', 'cet6-2026-06-3') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-1', 'original-cet6-2026-3', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Faced with growing global exchange, students need both cultural confidence and cultural curiosity. Cultural confidence allows them to explain the history behind their traditions. Cultural curiosity encourages them to listen when people from other backgrounds describe their experiences. Universities can create this opportunity through joint projects, language exchanges and visits to local cultural sites. The purpose is not to repeat a fixed image of culture, but to understand how traditions change while important memories remain. Such understanding makes international cooperation more respectful and creative."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-1-q-1', 'original-cet6-2026-3-section-1', 0, 'text', 'Write 150–200 words beginning with: “Faced with growing global exchange, students need both cultural confidence and cultural curiosity.”', '[]', 'Faced with growing global exchange, students need both cultural confidence and cultural curiosity. Cultural confidence allows them to explain the history behind their traditions. Cultural curiosity encourages them to listen when people from other backgrounds describe their experiences. Universities can create this opportunity through joint projects, language exchanges and visits to local cultural sites. The purpose is not to repeat a fixed image of culture, but to understand how traditions change while important memories remain. Such understanding makes international cooperation more respectful and creative.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-2', 'original-cet6-2026-3', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A museum used digital tools to create a new exhibition about local craft. The team [1] ______ the movements of experienced makers and invited young designers to [2] ______ them in a different form. Visitors could compare original objects with new designs. The project did not claim technology could [3] ______ skill. It showed how documentation could [4] ______ knowledge and make it [5] ______ to people who could not visit a workshop."]', '["A museum used digital tools to create a new exhibition about local craft. The team recorded the movements of experienced makers and invited young designers to interpret them in a different form. Visitors could compare original objects with new designs. The project did not claim technology could replace skill. It showed how documentation could preserve knowledge and make it accessible to people who could not visit a workshop."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
