INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-3', 'original-cet6-2026-3', 2, 'matching', '信息匹配 · 文化与全球协作', '根据段落内容完成匹配。', '["[A] A festival invited residents to teach a short craft activity. Translation cards helped visitors participate without a long speech.","[B] A dance group changed rehearsal time after students explained that evening classes conflicted with laboratory work. It kept the music and main movements.","[C] An archive digitised old letters but checked personal information and added context about the writers.","[D] Students compared two translations of a poem. They discussed what each version emphasised instead of choosing one as the only correct answer."]', '["A festival invited residents to teach a short craft activity. Translation cards helped visitors participate without a long speech.","A dance group changed rehearsal time after students explained that evening classes conflicted with laboratory work. It kept the music and main movements.","An archive digitised old letters but checked personal information and added context about the writers.","Students compared two translations of a poem. They discussed what each version emphasised instead of choosing one as the only correct answer."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-3-q-1', 'original-cet6-2026-3-section-3', 0, 'choice', 'Cultural access also requires ethical care.', '[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"}]', 'C', 'C段数字化前检查隐私并补充背景。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
