INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-4', 'original-cet6-2026-3', 3, 'reading', '阅读理解 · A place for both answers', '阅读短文，选择最合适的答案。', '["A university invited students to suggest a theme for a public art wall. One group wanted local history and another wanted an abstract future design. The facilitator asked what they wanted visitors to feel. The final design combined historical symbols with changing colours. The compromise worked because participants agreed on a purpose before a picture."]', '["A university invited students to suggest a theme for a public art wall. One group wanted local history and another wanted an abstract future design. The facilitator asked what they wanted visitors to feel. The final design combined historical symbols with changing colours. The compromise worked because participants agreed on a purpose before a picture."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-4-q-1', 'original-cet6-2026-3-section-4', 0, 'choice', 'Why did groups disagree?', '[{"key":"A","text":"They wanted different artistic directions."},{"key":"B","text":"They had no wall."},{"key":"C","text":"They refused to meet."},{"key":"D","text":"They discussed ticket prices."}]', 'A', '一组表现历史，另一组关注未来。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-4-q-2', 'original-cet6-2026-3-section-4', 1, 'choice', 'What question helped?', '[{"key":"A","text":"Who would clean the wall?"},{"key":"B","text":"What should visitors feel?"},{"key":"C","text":"Which group was larger?"},{"key":"D","text":"How much paint remained?"}]', 'B', '主持人让他们描述观众感受。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-4-q-3', 'original-cet6-2026-3-section-4', 2, 'choice', 'Why did compromise work?', '[{"key":"A","text":"They copied the first proposal."},{"key":"B","text":"They avoided history."},{"key":"C","text":"They shared a purpose."},{"key":"D","text":"The facilitator chose a winner."}]', 'C', '共同目的先于固定画面。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
