INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-5', 'original-cet6-2026-3', 4, 'reading', '阅读理解 · Power for a small business', '阅读短文，选择最合适的答案。', '["A rural training centre used a diesel generator for evening computer classes. Fuel prices rose and classes were cancelled when deliveries were late. A local engineer proposed solar power with batteries. It could not run every machine at once, so the centre changed its timetable and trained two residents to maintain it. Within a year, fuel costs fell and classes became more reliable."]', '["A rural training centre used a diesel generator for evening computer classes. Fuel prices rose and classes were cancelled when deliveries were late. A local engineer proposed solar power with batteries. It could not run every machine at once, so the centre changed its timetable and trained two residents to maintain it. Within a year, fuel costs fell and classes became more reliable."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-5-q-1', 'original-cet6-2026-3-section-5', 0, 'choice', 'What problem did the centre face?', '[{"key":"A","text":"Fuel shortages and rising costs."},{"key":"B","text":"No students."},{"key":"C","text":"A ban on computers."},{"key":"D","text":"Broken solar panels."}]', 'A', '燃料价格上涨且供应延迟。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-5-q-2', 'original-cet6-2026-3-section-5', 1, 'choice', 'How did it adapt?', '[{"key":"A","text":"It changed timetable and group size."},{"key":"B","text":"It ran every machine all day."},{"key":"C","text":"It stopped teaching."},{"key":"D","text":"It cancelled maintenance training."}]', 'A', '按照有限供电调整时间和班级。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-5-q-3', 'original-cet6-2026-3-section-5', 2, 'choice', 'What does the passage show?', '[{"key":"A","text":"Planning can make a limited resource reliable."},{"key":"B","text":"A system must power everything."},{"key":"C","text":"Residents cannot maintain technology."},{"key":"D","text":"Fuel is always cheaper."}]', 'A', '方案匹配有限电力和重要工作。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
