INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet6-2026-3-section-6', 'original-cet6-2026-3', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["中华文化在不断变化的社会中仍然具有生命力。年轻人通过学习传统节日、民间艺术和经典文学，能够更好地理解自己的文化背景。同时，他们也可以用新的方式讲述这些传统，使更多不同国家的人产生兴趣。"]', '["Chinese culture remains alive in a changing society. By learning about traditional festivals, folk arts and classic literature, young people can better understand their cultural background. They can also present these traditions in new ways and arouse interest among people from different countries."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet6-2026-3-section-6-q-1', 'original-cet6-2026-3-section-6', 0, 'text', '将上文译成英文。', '[]', 'Chinese culture remains alive in a changing society. By learning about traditional festivals, folk arts and classic literature, young people can better understand their cultural background. They can also present these traditions in new ways and arouse interest among people from different countries.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-neep-2026-1', 'NEEP', 2026, 10, 1, '主题练习', '考研主题练习 01 · 教育与人的成长', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2025-1', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考考研英语一的研究、证据和学术表达章节，全文为原创缩编内容。', 'neep-2025-1') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-1', 'original-neep-2026-1', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Examination results provide useful evidence of preparation, but practical experience should be valued highly in postgraduate education as well. Research requires students to formulate a problem, revise a method and respond when evidence contradicts an expectation. A balanced admission process could combine academic records with a small research proposal, an interview and evidence of sustained work. The criteria should be clear so applicants from different backgrounds can be compared fairly. Valuing practice does not mean lowering standards. It recognises that advanced study requires both knowledge and the ability to use it carefully."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-1-q-1', 'original-neep-2026-1-section-1', 0, 'text', 'Write a short essay on whether practical experience should be valued as highly as examination results in postgraduate education.', '[]', 'Examination results provide useful evidence of preparation, but practical experience should be valued highly in postgraduate education as well. Research requires students to formulate a problem, revise a method and respond when evidence contradicts an expectation. A balanced admission process could combine academic records with a small research proposal, an interview and evidence of sustained work. The criteria should be clear so applicants from different backgrounds can be compared fairly. Valuing practice does not mean lowering standards. It recognises that advanced study requires both knowledge and the ability to use it carefully.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-2', 'original-neep-2026-1', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A good research question is not always the most [1] ______ one. It is a question that can be [2] ______ with the time and evidence available. A student may begin with a broad [3] ______, then narrow it after reading earlier studies. This process helps the researcher [4] ______ what can be answered and what must remain uncertain. Clear limits often make a project more [5] ______."]', '["A good research question is not always the most ambitious one. It is a question that can be examined with the time and evidence available. A student may begin with a broad interest, then narrow it after reading earlier studies. This process helps the researcher identify what can be answered and what must remain uncertain. Clear limits often make a project more valuable."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
