INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-3', 'original-neep-2026-1', 2, 'matching', '信息匹配 · 教育与人的成长', '根据段落内容完成匹配。', '["[A] A supervisor asked a student to keep a research diary. It recorded successful experiments, method changes and reasons for abandoning an idea.","[B] A seminar began with a failed project. The speaker explained which assumption was wrong and what later work learned. Students asked more questions.","[C] A group shared data after removing personal identifiers. Both groups agreed how data could be reused and how results would be credited.","[D] A student traced an impressive statistic to its original survey and found a different population. She replaced it with a source whose method she could inspect."]', '["A supervisor asked a student to keep a research diary. It recorded successful experiments, method changes and reasons for abandoning an idea.","A seminar began with a failed project. The speaker explained which assumption was wrong and what later work learned. Students asked more questions.","A group shared data after removing personal identifiers. Both groups agreed how data could be reused and how results would be credited.","A student traced an impressive statistic to its original survey and found a different population. She replaced it with a source whose method she could inspect."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
