INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-4', 'original-neep-2026-1', 3, 'reading', '阅读理解 · The question after the result', '阅读短文，选择最合适的答案。', '["An experiment supported a student’s favourite explanation. The supervisor asked what other explanation could produce the same result. The student found that the experiment had not separated two causes. She changed the presentation to state evidence for one possibility, not proof of a final answer. Colleagues could then suggest a new test."]', '["An experiment supported a student’s favourite explanation. The supervisor asked what other explanation could produce the same result. The student found that the experiment had not separated two causes. She changed the presentation to state evidence for one possibility, not proof of a final answer. Colleagues could then suggest a new test."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
