INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-4-q-3', 'original-neep-2026-1-section-4', 2, 'choice', 'What did the careful conclusion do?', '[{"key":"A","text":"It made evidence and next test clearer."},{"key":"B","text":"It prevented discussion."},{"key":"C","text":"It proved the final answer."},{"key":"D","text":"It removed the result."}]', 'A', '谨慎表述明确证据范围。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
