INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-5', 'original-neep-2026-1', 4, 'reading', '阅读理解 · The value of a detour', '阅读短文，选择最合适的答案。', '["A graduate student planned to study one archive, but it closed for repairs. An adviser suggested visiting a smaller local collection and interviewing its archivist. The detour revealed letters that changed the student’s understanding. It did not completely replace the original archive, so she revised her question and stated the limitation. The project became more modest but more original."]', '["A graduate student planned to study one archive, but it closed for repairs. An adviser suggested visiting a smaller local collection and interviewing its archivist. The detour revealed letters that changed the student’s understanding. It did not completely replace the original archive, so she revised her question and stated the limitation. The project became more modest but more original."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-5-q-1', 'original-neep-2026-1-section-5', 0, 'choice', 'Why could she not use the original archive?', '[{"key":"A","text":"It was closed for repairs."},{"key":"B","text":"It moved overseas."},{"key":"C","text":"It refused interviews."},{"key":"D","text":"It contained no letters."}]', 'A', '原档案馆因维修关闭。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-5-q-2', 'original-neep-2026-1-section-5', 1, 'choice', 'What did the local collection reveal?', '[{"key":"A","text":"Letters that changed her understanding."},{"key":"B","text":"A complete replacement."},{"key":"C","text":"A reason to abandon research."},{"key":"D","text":"A new language."}]', 'A', '地方馆藏发现了改变理解的信件。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-5-q-3', 'original-neep-2026-1-section-5', 2, 'choice', 'What did she do about the limitation?', '[{"key":"A","text":"She revised the question and stated it clearly."},{"key":"B","text":"She hid it."},{"key":"C","text":"She claimed the archive was complete."},{"key":"D","text":"She stopped citing sources."}]', 'A', '她调整问题并明确局限。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
