INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-1-section-6', 'original-neep-2026-1', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["研究生教育不仅要求学生掌握专业知识，还要求他们能够独立思考、清楚表达并承担研究责任。一个好的研究项目不一定会立即得到确定的答案，但它应该提出有意义的问题，并通过可靠的证据不断修正理解。"]', '["Postgraduate education requires students not only to master specialised knowledge, but also to think independently, express themselves clearly and take responsibility for their research. A good research project may not produce a definite answer immediately, but it should raise a meaningful question and improve our understanding through reliable evidence."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-1-section-6-q-1', 'original-neep-2026-1-section-6', 0, 'text', '将上文译成英文。', '[]', 'Postgraduate education requires students not only to master specialised knowledge, but also to think independently, express themselves clearly and take responsibility for their research. A good research project may not produce a definite answer immediately, but it should raise a meaningful question and improve our understanding through reliable evidence.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-neep-2026-2', 'NEEP', 2026, 10, 2, '主题练习', '考研主题练习 02 · 社会变化与公共生活', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2025-2', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考考研英语二的医疗、城市和公共资源章节，全文为原创缩编内容。', 'neep-2025-2') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-1', 'original-neep-2026-2', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Public services should be evaluated by accessibility as well as efficiency. A service may process applications quickly, but it cannot be successful if older people, people with disabilities or residents without stable internet cannot use it. Governments can measure waiting times while also testing forms with different users and offering several channels. These steps may require more staff at first, but they can prevent repeated applications and reduce hidden costs. Efficient systems save resources. Accessible systems make sure those resources benefit people fairly. Good public administration needs both qualities."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-2-section-1-q-1', 'original-neep-2026-2-section-1', 0, 'text', 'Write a short essay discussing why public services should be evaluated by accessibility as well as efficiency.', '[]', 'Public services should be evaluated by accessibility as well as efficiency. A service may process applications quickly, but it cannot be successful if older people, people with disabilities or residents without stable internet cannot use it. Governments can measure waiting times while also testing forms with different users and offering several channels. These steps may require more staff at first, but they can prevent repeated applications and reduce hidden costs. Efficient systems save resources. Accessible systems make sure those resources benefit people fairly. Good public administration needs both qualities.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-2', 'original-neep-2026-2', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["A health system may improve when it moves care closer to people’s homes. Local clinics can [1] ______ minor problems from becoming emergencies and [2] ______ patients with specialists when necessary. However, a reform should not simply [3] ______ work without staff and equipment. Policymakers need to [4] ______ results and listen to patients. Otherwise, an efficient change may [5] ______ new delays elsewhere."]', '["A health system may improve when it moves care closer to people’s homes. Local clinics can prevent minor problems from becoming emergencies and connect patients with specialists when necessary. However, a reform should not simply transfer work without staff and equipment. Policymakers need to monitor results and listen to patients. Otherwise, an efficient change may create new delays elsewhere."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
