INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-3', 'original-neep-2026-2', 2, 'matching', '信息匹配 · 社会变化与公共生活', '根据段落内容完成匹配。', '["[A] A city redesigned a square after watching how people crossed it. New paths followed common walking routes instead of forcing everyone around a garden.","[B] A clinic used several languages and pictures for people with limited literacy. Volunteers tested the signs with visitors.","[C] A food bank changed opening hours after finding that many visitors worked then.","[D] A council compared a road plan with maintaining buses. The cheaper option would remove a stop used by people without cars."]', '["A city redesigned a square after watching how people crossed it. New paths followed common walking routes instead of forcing everyone around a garden.","A clinic used several languages and pictures for people with limited literacy. Volunteers tested the signs with visitors.","A food bank changed opening hours after finding that many visitors worked then.","A council compared a road plan with maintaining buses. The cheaper option would remove a stop used by people without cars."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-2-section-3-q-1', 'original-neep-2026-2-section-3', 0, 'choice', 'A schedule can determine who benefits from a service.', '[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"}]', 'C', 'C段改变时间后在职居民更容易领取食物。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
