INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-4', 'original-neep-2026-2', 3, 'reading', '阅读理解 · The queue that moved elsewhere', '阅读短文，选择最合适的答案。', '["A hospital introduced online booking and celebrated a shorter telephone queue. Patients unable to use the tool arrived in person, crowding reception. The hospital trained volunteers, kept a small telephone service and explained appointment allocation. It stopped treating a shorter phone queue as the only sign of success: a queue may disappear from one place while growing in another."]', '["A hospital introduced online booking and celebrated a shorter telephone queue. Patients unable to use the tool arrived in person, crowding reception. The hospital trained volunteers, kept a small telephone service and explained appointment allocation. It stopped treating a shorter phone queue as the only sign of success: a queue may disappear from one place while growing in another."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
