INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-5', 'original-neep-2026-2', 4, 'reading', '阅读理解 · The cost of a quiet street', '阅读短文，选择最合适的答案。', '["A town planned to close a central street to cars on weekends. Shop owners worried about deliveries and parents wanted safety. A six-week trial allowed deliveries before noon and collected reports. Pedestrian numbers rose, but a side street became crowded. The council adjusted signs and continued the closure with a delivery window."]', '["A town planned to close a central street to cars on weekends. Shop owners worried about deliveries and parents wanted safety. A six-week trial allowed deliveries before noon and collected reports. Pedestrian numbers rose, but a side street became crowded. The council adjusted signs and continued the closure with a delivery window."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
