INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-2-section-6', 'original-neep-2026-2', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["随着人口老龄化，许多社区开始重新思考公共服务的安排。除了提供医疗和照护，社区还需要建设方便步行的道路、可以交流的公共空间以及帮助老年人使用数字服务的支持网络。"]', '["As the population ages, many communities are reconsidering how public services should be arranged. In addition to medical care and support, communities need walkable streets, public spaces for interaction and networks that help older people use digital services."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-2-section-6-q-1', 'original-neep-2026-2-section-6', 0, 'text', '将上文译成英文。', '[]', 'As the population ages, many communities are reconsidering how public services should be arranged. In addition to medical care and support, communities need walkable streets, public spaces for interaction and networks that help older people use digital services.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-neep-2026-3', 'NEEP', 2026, 10, 3, '主题练习', '考研主题练习 03 · 证据与复杂问题', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2024-1', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。参考考研英语一的历史材料、人工智能和环境治理章节，全文为原创缩编内容。', 'neep-2024-1') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-1', 'original-neep-2026-3', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["Researchers should balance a clear conclusion with uncertainty by stating exactly what their evidence can support. A conclusion that lists every doubt may be impossible to use, but a confident claim that hides limitations can mislead readers. Researchers can separate the main finding from the conditions under which it was observed, explain what remains unknown and suggest a test that could reduce uncertainty. Clarity tells us what the evidence shows, while uncertainty tells us how far we should go."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-1-q-1', 'original-neep-2026-3-section-1', 0, 'text', 'Write a short essay on how researchers should balance a clear conclusion with uncertainty in their evidence.', '[]', 'Researchers should balance a clear conclusion with uncertainty by stating exactly what their evidence can support. A conclusion that lists every doubt may be impossible to use, but a confident claim that hides limitations can mislead readers. Researchers can separate the main finding from the conditions under which it was observed, explain what remains unknown and suggest a test that could reduce uncertainty. Clarity tells us what the evidence shows, while uncertainty tells us how far we should go.', '关注任务完成、论证/结构、语言准确性和字数要求。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-2', 'original-neep-2026-3', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["Historical objects can answer questions only when studied in [1] ______. A single letter may seem to [2] ______ a whole society, but its writer had a particular purpose and audience. Researchers [3] ______ it with other records and [4] ______ what is missing. Digital tools can make collections more [5] ______, yet they cannot automatically explain why an object was created."]', '["Historical objects can answer questions only when studied in context. A single letter may seem to reveal a whole society, but its writer had a particular purpose and audience. Researchers compare it with other records and consider what is missing. Digital tools can make collections more accessible, yet they cannot automatically explain why an object was created."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
