INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-3', 'original-neep-2026-3', 2, 'matching', '信息匹配 · 证据与复杂问题', '根据段落内容完成匹配。', '["[A] A museum displayed old tools beside modern versions. Visitors handled safe replicas and read about materials. The aim was to show the problems each object solved, not simply rank old and new.","[B] An archive noted that a photograph was taken by a colonial official. It explained whose viewpoint was present and which people could not record their own experiences.","[C] An AI image tool reconstructed a historical street. The team labelled it as a reconstruction and linked the sources.","[D] A coastal town restored wetlands after floods. Engineers measured water, and residents described earlier flows."]', '["A museum displayed old tools beside modern versions. Visitors handled safe replicas and read about materials. The aim was to show the problems each object solved, not simply rank old and new.","An archive noted that a photograph was taken by a colonial official. It explained whose viewpoint was present and which people could not record their own experiences.","An AI image tool reconstructed a historical street. The team labelled it as a reconstruction and linked the sources.","A coastal town restored wetlands after floods. Engineers measured water, and residents described earlier flows."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
