INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-4', 'original-neep-2026-3', 3, 'reading', '阅读理解 · The missing comparison', '阅读短文，选择最合适的答案。', '["A report claimed a new teaching method raised scores by comparing one class before and after. It did not compare a class using the old method. A later review found the new class also received extra sessions and had a different timetable. The school began a broader trial with comparable classes before making a strong claim."]', '["A report claimed a new teaching method raised scores by comparing one class before and after. It did not compare a class using the old method. A later review found the new class also received extra sessions and had a different timetable. The school began a broader trial with comparable classes before making a strong claim."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-4-q-1', 'original-neep-2026-3-section-4', 0, 'choice', 'What comparison was missing?', '[{"key":"A","text":"A class using the old method."},{"key":"B","text":"Furniture lists."},{"key":"C","text":"School colours."},{"key":"D","text":"Holiday records."}]', 'A', '没有比较继续使用旧方法的班级。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-4-q-2', 'original-neep-2026-3-section-4', 1, 'choice', 'What other difference existed?', '[{"key":"A","text":"Extra sessions and a different timetable."},{"key":"B","text":"No teacher."},{"key":"C","text":"All scores were identical."},{"key":"D","text":"The method was never used."}]', 'A', '新班级另有额外学习和不同时间表。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-4-q-3', 'original-neep-2026-3-section-4', 2, 'choice', 'What did school do next?', '[{"key":"A","text":"It began a broader trial with comparable classes."},{"key":"B","text":"It declared proof."},{"key":"C","text":"It stopped evidence."},{"key":"D","text":"It removed study sessions."}]', 'A', '开展有可比班级的更大试验。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
