INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-5', 'original-neep-2026-3', 4, 'reading', '阅读理解 · A shoreline with two records', '阅读短文，选择最合适的答案。', '["A coastal village kept weather-station measurements and fishers’ marks of where waves reached the harbour wall. A planner noticed that fishers had recorded short storms the station missed. The records did not always agree, but together they showed where water moved quickly. Local observation did not replace instruments; it showed them where to look closely."]', '["A coastal village kept weather-station measurements and fishers’ marks of where waves reached the harbour wall. A planner noticed that fishers had recorded short storms the station missed. The records did not always agree, but together they showed where water moved quickly. Local observation did not replace instruments; it showed them where to look closely."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-5-q-1', 'original-neep-2026-3-section-5', 0, 'choice', 'What were the two records?', '[{"key":"A","text":"Station measurements and fishers’ observations."},{"key":"B","text":"Building plans."},{"key":"C","text":"School reports and taxes."},{"key":"D","text":"Satellite pictures and traffic."}]', 'A', '两类记录分别来自气象站和渔民。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-5-q-2', 'original-neep-2026-3-section-5', 1, 'choice', 'Why compare them?', '[{"key":"A","text":"Fishers noted storms the station missed."},{"key":"B","text":"The station closed."},{"key":"C","text":"The wall disappeared."},{"key":"D","text":"Records were identical."}]', 'A', '渔民记录了气象站遗漏的风暴。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-5-q-3', 'original-neep-2026-3-section-5', 2, 'choice', 'What was local observation’s role?', '[{"key":"A","text":"It guided closer measurement."},{"key":"B","text":"It replaced instruments."},{"key":"C","text":"It prevented barriers."},{"key":"D","text":"It proved every memory exact."}]', 'A', '当地观察补充并引导仪器测量。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
