INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-neep-2026-3-section-5-sentence-1-3', 'original-neep-2026-3', 400, 2, 'The records did not always agree, but together they showed where water moved quickly.', 'original-neep-2026-3-section-5') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
