INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-neep-2026-3-section-6', 'original-neep-2026-3', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["环境治理需要长期的观察和合作。科学家可以通过仪器收集数据，居民则能够提供对当地变化的日常经验。把这两类知识结合起来，有助于发现风险、改进政策，并让更多人理解保护环境为什么需要持续行动。"]', '["Environmental governance requires long-term observation and cooperation. Scientists can collect data with instruments, while residents can offer everyday knowledge of local changes. Combining these kinds of knowledge helps identify risks, improve policies and show why environmental protection requires sustained action."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-neep-2026-3-section-6-q-1', 'original-neep-2026-3-section-6', 0, 'text', '将上文译成英文。', '[]', 'Environmental governance requires long-term observation and cooperation. Scientists can collect data with instruments, while residents can offer everyday knowledge of local changes. Combining these kinds of knowledge helps identify risks, improve policies and show why environmental protection requires sustained action.', '可采用不同措辞；重点核对信息完整性、逻辑关系和表达准确性。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
